const preplySchedules = {"1": "Monday, Aug 10, 2026 (22:00 - 22:50)", "2": "Friday, Aug 14, 2026 (22:00 - 22:50)", "3": "Monday, Aug 17, 2026 (22:00 - 22:50)", "4": "Friday, Aug 21, 2026 (22:00 - 22:50)", "5": "Monday, Aug 24, 2026 (22:00 - 22:50)", "6": "Friday, Aug 28, 2026 (22:00 - 22:50)", "7": "Monday, Aug 31, 2026 (22:00 - 22:50)", "8": "Friday, Sep 04, 2026 (22:00 - 22:50)"};

document.addEventListener("DOMContentLoaded", () => {
    fetchLessonsAndRender();
    
    document.getElementById('dict-search-input').addEventListener('keypress', (e) => {
        if (e.key === 'Enter') searchOxfordDict();
    });
});

function speakText(text) {
    if ('speechSynthesis' in window) {
        window.speechSynthesis.cancel();
        const cleanText = text.replace(/\(.*?\)/g, '').replace(/[^\x00-\x7F]/g, '');
        const utterance = new SpeechSynthesisUtterance(cleanText);
        utterance.lang = 'en-US';
        utterance.rate = 0.92;
        window.speechSynthesis.speak(utterance);
    } else {
        alert("Trình duyệt không hỗ trợ phát âm.");
    }
}

async function searchOxfordDict() {
    const word = document.getElementById('dict-search-input').value.trim();
    if (!word) return;
    const box = document.getElementById('dict-modal-result');
    box.style.display = 'block';
    box.innerHTML = "<p>🔍 Đang tra từ điển Oxford...</p>";

    try {
        const res = await fetch(`/api/dictionary?word=${encodeURIComponent(word)}`);
        const result = await res.json();
        if (result.found && result.data) {
            const d = result.data;
            box.innerHTML = `
                <div style="display:flex; justify-content:space-between; align-items:center;">
                    <h3 style="color:#0f172a; font-size:1.15rem;">📖 Oxford Standard: <span style="color:#2563eb;">${d.word}</span> <span style="color:#64748b; font-size:0.85rem;">${d.ipa}</span></h3>
                    <button class="speech-icon-btn" onclick="speakText('${d.word}')">🔊 Phát âm từ</button>
                </div>
                <p style="margin-top:0.4rem;"><strong>Loại từ:</strong> <em style="color:#d97706;">${d.pos}</em> | <strong>Nghĩa VI:</strong> <strong style="color:#065f46;">${d.vi}</strong></p>
                <p style="margin-top:0.4rem; color:#334155;"><strong>Định nghĩa:</strong> ${d.def}</p>
                <p style="margin-top:0.4rem; font-style:italic; color:#475569;"><strong>Ví dụ:</strong> "${d.ex}" <button class="speech-icon-btn" onclick="speakText('${d.ex.replace(/'/g, "\\'")}}')">🔊 Đọc ví dụ</button></p>
            `;
        }
    } catch (e) {
        box.innerHTML = `<p style="color:#ef4444;">Lỗi tra từ: ${e.message}</p>`;
    }
}

async function fetchLessonsAndRender() {
    try {
        const res = await fetch('/api/lessons');
        if (res.ok) {
            const data = await res.json();
            let fetched = [];
            if (Array.isArray(data)) fetched = data;
            else if (data && Array.isArray(data.lessons)) fetched = data.lessons;
            
            if (fetched.length > 0) {
                globalLessons = fetched;
            }
        }
    } catch (e) {
        console.warn("Using bulletproof preply schedule fallback lessons:", e.message);
    }
    
    renderSidebarMenu();
    if (globalLessons.length > 0) {
        selectLesson(globalLessons[0].id);
    }
}

function renderSidebarMenu() {
    const sidebar = document.getElementById('sidebar-lesson-list');
    sidebar.innerHTML = globalLessons.map(l => {
        const dateStr = l.scheduleDate || preplySchedules[l.id] || 'Monday, Aug 10, 2026 (22:00 - 22:50)';
        return `
            <div class="sidebar-item ${l.id === activeLessonId ? 'active' : ''}" onclick="selectLesson(${l.id})">
                <div><strong>Buổi ${l.id < 10 ? '0' + l.id : l.id}:</strong> ${l.title.replace(/^Lesson \d+:\s*/i, '')}</div>
                <div class="sidebar-item-date">📅 ${dateStr}</div>
            </div>
        `;
    }).join('');
}

